import{_ as a,o as e,c as l,a2 as d}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"充值余额","description":"","frontmatter":{},"headers":[],"relativePath":"account/top-up.md","filePath":"account/top-up.md","lastUpdated":1784973959000}'),r={name:"account/top-up.md"};function i(o,t,c,n,h,p){return e(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="充值余额" tabindex="-1">充值余额 <a class="header-anchor" href="#充值余额" aria-label="Permalink to &quot;充值余额&quot;">​</a></h1><p>余额充值用于给 DouDi.ai 账户增加可消费额度。公开前端文案显示，充值成功后额度会进入钱包；支付可能以人民币结算，页面会展示实际支付金额、到账额度、订单号、支付方式和充值前后余额。</p><h2 id="充值步骤" tabindex="-1">充值步骤 <a class="header-anchor" href="#充值步骤" aria-label="Permalink to &quot;充值步骤&quot;">​</a></h2><ol><li>登录 <a href="https://doudi.ai" target="_blank" rel="noreferrer">https://doudi.ai</a>。</li><li>进入控制台中的 <code>Wallet</code>。</li><li>查看当前余额和充值入口。</li><li>选择或输入充值金额。</li><li>选择支付方式。</li><li>确认支付金额和到账额度。</li><li>支付完成后回到 <code>Wallet</code> 查看余额是否更新。</li></ol><h2 id="页面中可能看到的字段" tabindex="-1">页面中可能看到的字段 <a class="header-anchor" href="#页面中可能看到的字段" aria-label="Permalink to &quot;页面中可能看到的字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Balance</td><td>当前余额。</td></tr><tr><td>Wallet credit</td><td>充值额度。</td></tr><tr><td>Amount to pay</td><td>待支付金额。</td></tr><tr><td>Actual payment</td><td>实际支付金额。</td></tr><tr><td>Credited Quota</td><td>到账额度。</td></tr><tr><td>Balance Before</td><td>充值前余额。</td></tr><tr><td>Balance After</td><td>充值后余额。</td></tr><tr><td>Order Number</td><td>订单号。</td></tr><tr><td>Payment Request IP</td><td>付款请求 IP。</td></tr></tbody></table><h2 id="支付方式" tabindex="-1">支付方式 <a class="header-anchor" href="#支付方式" aria-label="Permalink to &quot;支付方式&quot;">​</a></h2><p>前端配置中出现了支付宝、微信、Stripe、USDT 网络和自定义支付方式等能力。你实际能看到哪些支付方式，取决于 DouDi.ai 当前后台配置。</p><p>如果页面提示“尚未启用在线充值”，可以使用兑换码或联系管理员。</p><h2 id="折扣与最低充值" tabindex="-1">折扣与最低充值 <a class="header-anchor" href="#折扣与最低充值" aria-label="Permalink to &quot;折扣与最低充值&quot;">​</a></h2><p>站点前端包含金额折扣、最低充值金额和优惠提示相关文案，例如：</p><ul><li>充值金额可能有最低要求。</li><li>不同充值金额可能对应不同折扣。</li><li>页面可能显示节省金额或折扣百分比。</li></ul><p>充值前请重点核对两件事：</p><ol><li>实际支付金额。</li><li>支付成功后到账额度。</li></ol><h2 id="充值后如何确认到账" tabindex="-1">充值后如何确认到账 <a class="header-anchor" href="#充值后如何确认到账" aria-label="Permalink to &quot;充值后如何确认到账&quot;">​</a></h2><ol><li>查看 <code>Wallet</code> 当前余额是否增加。</li><li>查看钱包流水中是否出现新记录。</li><li>查看订单状态是否为成功或可用。</li><li>如果余额没有变化，保留订单号和支付截图后联系平台处理。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>给生产项目充值前，建议先用小额充值验证支付链路和到账逻辑。</p></div>',17)])])}const _=a(r,[["render",i]]);export{u as __pageData,_ as default};
